def f_Piggybank__explode(_item):
    particles = None
    pool = None
    value = None
    item = None
    particles = _const_ObjectPool.particleOneShot(_item.breakParticles, _item.get_parent())
    pass
    pass
    if _item._behavior_call('hasPinata'):
        pool = _const_ItemPool.new()
        for descr in _const__range_or_value(_item.ctx.item_book.items.values()):
            if descr != _item.descriptor and _item.ctx.item_book.canBeGenerated(descr, _item.pinataFilter):
                pool.addItem(descr)
        pool.pool
        pool.sortItems()
        pool.sellPrice = True
        value = 7
        while value > 0:
            pool.setPrice(value)
            item = pool.getRandomItemTopHeavy()
            value -= item.get_sell_price()
            pass
