def f_Chess_Board__findBestPieceToCapture(_item, activePieces=None):
    bestMovePiece = None
    bestMoveCapture = None
    bestMoveScore = None
    captureCells = None
    globalCell = None
    itemInCell = None
    score = None
    length = None
    dir = None
    cellToCheck = None
    itemThere = None
    bestMovePiece = None
    bestMoveCapture = None
    bestMoveScore = -10000
    for piece in _const__range_or_value(activePieces):
        captureCells = piece.getCaptureCells()
        captureCells
        for cell in _const__range_or_value(captureCells):
            globalCell = piece.occupiedCells[0] + cell
            itemInCell = _item.character_().get_items().getItemInCell(globalCell)
            if itemInCell != None and piece.can_affect(itemInCell):
                score = itemInCell.get_price()
                if score > bestMoveScore:
                    if piece.canBeBlocked():
                        length = max(abs(cell.x), abs(cell.y))
                        if length > 1:
                            dir = cell / length
                            for i in _const__range_or_value(range(1, length)):
                                cellToCheck = piece.occupiedCells[0] + i * dir
                                itemThere = _item.character_().get_items().getItemInCell(cellToCheck)
                                if itemThere != None and itemThere.has_type(_const_Type.ChessPiece):
                                    score -= 100
                                    break
                    if score > bestMoveScore:
                        bestMoveScore = score
                        bestMoveCapture = itemInCell
                        bestMovePiece = piece
    if bestMoveCapture != None:
        return [bestMovePiece, bestMoveCapture]
    else:
        return None
