def f_Item__getSizeInCells(_item):
    topLeft = None
    bottomRight = None
    cells = None
    topLeft = _const_Vector2(100, 100)
    bottomRight = _const_Vector2(-100, -100)
    cells = _item._behavior_call('getCollisionCells')
    if not cells:
        return _const_Vector2.ZERO
    for cell in _const__range_or_value(cells):
        if cell.x < topLeft.x:
            topLeft.x = cell.x
        if cell.y < topLeft.y:
            topLeft.y = cell.y
        if cell.x > bottomRight.x:
            bottomRight.x = cell.x
        if cell.y > bottomRight.y:
            bottomRight.y = cell.y
    return bottomRight - topLeft + _const_Vector2(1, 1)
